// The previous (Jekyll/Chirpy) site registered a cache-first service worker at this URL.
// This replacement clears its caches, unregisters itself, and reloads open tabs so
// returning visitors see the current site instead of a stale copy.
self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.map((key) => caches.delete(key)));
      await self.registration.unregister();
      const clients = await self.clients.matchAll({ type: 'window' });
      for (const client of clients) client.navigate(client.url);
    })(),
  );
});
